#include <string>
#include <utility>
#include <vector>

class Report {
public:
    void set_data(std::vector<double> d) { data_ = std::move(d); }  // sink: by value + move.
private:
    std::vector<double> data_;
};

std::vector<double> load();                 // returned values move automatically.

int main() {
    std::vector<double> readings(1'000'000, 0.5);
    Report r;
    r.set_data(readings);                   // COPY: readings still needed later.
    r.set_data(std::move(readings));        // MOVE: buffer transferred; we're done with it.
    readings = {1.0, 2.0};                  // fine: assign a fresh value.
    // readings.size() before the assignment: valid but unspecified. Don't rely on it.

    r.set_data(load());                     // temporary: moved without std::move.
    std::string a = "long text...";
    std::string b = std::move(a);           // a is valid but unspecified now.
}
```

| Expression | Copy or move? |
|---|---|
| `f(x)` with a named x. | copy. |
| `f(std::move(x))`. | move (x is expiring). |
| `f(make_thing())`. | move (temporary). |
| `return local;`. | move or elided (no std::move needed). |

